values ('d27119e1-3945-5219-9748-6e9b40746f99', null, '{"nl":"Shakshuka","en":"Shakshuka","de":"Shakshuka"}'::jsonb, '{"nl":["Snijd ui, paprika en knoflook en bak ze 5 minuten zacht in de olie.","Voeg tomaten, komijn en paprikapoeder toe en laat 10 minuten zachtjes koken.","Maak vier kuiltjes, breek er de eieren in en laat ze met de deksel erop 6 tot 8 minuten stollen.","Strooi de koriander erover en eet met het brood."],"en":["Chop the onion, pepper and garlic and soften them in the oil for 5 minutes.","Add the tomatoes, cumin and paprika and simmer for 10 minutes.","Make four hollows, crack in the eggs and cook covered for 6 to 8 minutes until set.","Scatter over the coriander and serve with the bread."],"de":["Zwiebel, Paprika und Knoblauch schneiden und 5 Minuten im Öl weich braten.","Tomaten, Kreuzkümmel und Paprikapulver zugeben und 10 Minuten köcheln lassen.","Vier Mulden machen, die Eier hineingeben und zugedeckt 6 bis 8 Minuten stocken lassen.","Mit Koriander bestreuen und mit dem Brot servieren."]}'::jsonb, 2, 25, 406.3, 22.2, 42.1, 18.5, false, array['breakfast', 'lunch']::text[], array['egg', 'gluten']::text[], '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
