values ('b3f60ead-a4eb-5607-b111-dee941b6056a', null, '{"nl":"Omelet met spinazie en feta","en":"Spinach and feta omelette","de":"Omelett mit Spinat und Feta"}'::jsonb, '{"nl":["Klop de eieren los met een snuf peper.","Laat de spinazie in de olie slinken, giet de eieren erover en laat ze op laag vuur stollen.","Verkruimel de feta erover, vouw dubbel en eet met het brood."],"en":["Beat the eggs with a pinch of pepper.","Wilt the spinach in the oil, pour over the eggs and let them set over a low heat.","Crumble over the feta, fold in half and serve with the bread."],"de":["Die Eier mit etwas Pfeffer verquirlen.","Den Spinat im Öl zusammenfallen lassen, die Eier darübergießen und bei schwacher Hitze stocken lassen.","Feta darüberbröseln, zusammenklappen und mit dem Brot servieren."]}'::jsonb, 1, 10, 402.6, 27.5, 18.6, 24, false, array['breakfast']::text[], array['egg', 'dairy', 'gluten']::text[], '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
