values ('1ca50143-050d-5639-b188-6fadc679ed03', null, '{"nl":"Havermout met appel en kaneel","en":"Apple cinnamon porridge","de":"Haferbrei mit Apfel und Zimt"}'::jsonb, '{"nl":["Breng havermout en melk aan de kook en laat 4 minuten zachtjes koken, al roerend.","Snijd de appel in blokjes en roer hem met de kaneel door de pap.","Hak de amandelen grof en strooi ze met de honing erover."],"en":["Bring the oats and milk to the boil and simmer for 4 minutes, stirring.","Dice the apple and stir it into the porridge with the cinnamon.","Roughly chop the almonds and scatter them over with the honey."],"de":["Haferflocken und Milch aufkochen und unter Rühren 4 Minuten köcheln lassen.","Den Apfel würfeln und mit dem Zimt unter den Brei rühren.","Die Mandeln grob hacken und mit dem Honig darübergeben."]}'::jsonb, 2, 10, 429.8, 15.6, 67.9, 12.4, false, array['breakfast']::text[], array['dairy', 'nuts', 'gluten']::text[], '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
