values ('0f250847-4778-59c9-b80f-87bda7c3e799', null, '{"nl":"Caesarsalade met kip","en":"Chicken Caesar salad","de":"Caesar Salad mit Hähnchen"}'::jsonb, '{"nl":["Bak de kip in de helft van de olie in 10 minuten gaar en snijd hem in reepjes.","Rooster het brood in blokjes in de rest van de olie tot croutons.","Roer yoghurt, citroensap, geperste knoflook en de helft van de kaas tot een dressing.","Meng de sla met de dressing en leg kip, croutons en de rest van de kaas erop."],"en":["Cook the chicken in half the oil for 10 minutes and slice it.","Toast the bread in cubes in the rest of the oil to make croutons.","Stir the yoghurt, lemon juice, crushed garlic and half the cheese into a dressing.","Toss the lettuce with the dressing and top with the chicken, croutons and remaining cheese."],"de":["Das Hähnchen in der Hälfte des Öls 10 Minuten braten und in Streifen schneiden.","Das Brot in Würfeln im restlichen Öl zu Croûtons rösten.","Joghurt, Zitronensaft, gepressten Knoblauch und die Hälfte des Käses zu einem Dressing verrühren.","Den Salat mit dem Dressing mischen und mit Hähnchen, Croûtons und restlichem Käse belegen."]}'::jsonb, 2, 20, 450.3, 49, 24.1, 17.2, false, array['lunch', 'dinner']::text[], array['meat', 'dairy', 'gluten']::text[], '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
