values ('d961ceed-d229-5d4e-a571-21b7caaa956d', null, '{"nl":"Boerenkoolstamppot met rookworst","en":"Kale mash with smoked sausage","de":"Grünkohleintopf mit Räucherwurst"}'::jsonb, '{"nl":["Kook de aardappelen 20 minuten met de boerenkool erop.","Verwarm de rookworst 10 minuten in heet water.","Giet af en stamp met warme melk en boter. Serveer met plakjes rookworst."],"en":["Boil the potatoes for 20 minutes with the kale on top.","Heat the sausage in hot water for 10 minutes.","Drain and mash with the warm milk and butter. Serve with slices of sausage."],"de":["Die Kartoffeln mit dem Grünkohl obenauf 20 Minuten kochen.","Die Räucherwurst 10 Minuten in heißem Wasser erwärmen.","Abgießen und mit warmer Milch und Butter stampfen. Mit Wurstscheiben servieren."]}'::jsonb, 4, 35, 540.4, 19.3, 61.5, 25.7, true, array['dinner']::text[], array['meat', 'dairy']::text[], '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
