values ('b811c29b-e554-559c-9cb3-5dc38b366e08', null, '{"nl":"Lasagne met spinazie","en":"Spinach lasagne","de":"Lasagne mit Spinat"}'::jsonb, '{"nl":["Maak een saus: fruit ui, knoflook en wortel, bak het gehakt rul en laat 20 minuten koken met tomaten, tomatenpuree en oregano.","Meng de hüttenkäse met de spinazie.","Leg in een ovenschaal laagjes saus, lasagnebladen en spinaziemengsel, eindig met saus en mozzarella.","Bak 35 minuten op 190 °C."],"en":["Make a sauce: fry the onion, garlic and carrot, brown the mince and simmer for 20 minutes with the tomatoes, tomato paste and oregano.","Mix the cottage cheese with the spinach.","Layer sauce, lasagne sheets and the spinach mixture in an ovenproof dish, finishing with sauce and mozzarella.","Bake for 35 minutes at 190 °C."],"de":["Eine Soße kochen: Zwiebel, Knoblauch und Karotte anbraten, das Hackfleisch krümelig braten und mit Tomaten, Tomatenmark und Oregano 20 Minuten köcheln lassen.","Den Hüttenkäse mit dem Spinat mischen.","In einer Auflaufform Soße, Lasagneplatten und Spinatmischung schichten, mit Soße und Mozzarella abschließen.","35 Minuten bei 190 °C backen."]}'::jsonb, 6, 75, 522.2, 42.2, 49.1, 17.7, true, array['dinner']::text[], array['meat', 'dairy', 'gluten']::text[], '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
