values ('ddfc9b2e-2d3b-5c6b-ae3d-e0994230689e', null, '{"nl":"Gebakken rijst met ei","en":"Egg fried rice","de":"Gebratener Reis mit Ei"}'::jsonb, '{"nl":["Kook de rijst een dag van tevoren en laat hem afkoelen.","Roerbak wortel, erwten en knoflook 4 minuten in de olie, schuif opzij en roerei de eieren erbij.","Voeg rijst en sojasaus toe, bak 3 minuten op hoog vuur en strooi de lente-ui erover."],"en":["Cook the rice the day before and let it cool.","Stir-fry the carrot, peas and garlic in the oil for 4 minutes, push aside and scramble the eggs in the pan.","Add the rice and soy sauce, fry over a high heat for 3 minutes and scatter over the spring onion."],"de":["Den Reis am Vortag kochen und abkühlen lassen.","Karotte, Erbsen und Knoblauch 4 Minuten im Öl pfannenrühren, beiseiteschieben und die Eier darin stocken lassen.","Reis und Sojasoße zugeben, 3 Minuten bei starker Hitze braten und mit Frühlingszwiebel bestreuen."]}'::jsonb, 3, 20, 498.8, 18.7, 78.4, 11.6, false, array['lunch', 'dinner']::text[], array['egg', 'soy']::text[], '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
